using ASimpleMinecraftServer.Models; using System.Collections.ObjectModel; using System.IO; using System.Windows; using System.Windows.Controls; namespace ASimpleMinecraftServer.UI.Pages; public partial class OptimizationView:UserControl { private ServerProfile? _profile; private readonly ObservableCollection<OptimizationRecommendation> _items=new(); public OptimizationView(){InitializeComponent();ItemsGrid.ItemsSource=_items;} public void Bind(ServerProfile? p){_profile=p;GenerateButton.IsEnabled=p is not null;SummaryText.Text=p is null?"Select a server first.":$"Generate recommendations for {p.Name}.";} private void Generate_Click(object sender,RoutedEventArgs e){_items.Clear();if(_profile is null)return;var props=ReadProps();var view=GetInt(props,"view-distance",10);var sim=GetInt(props,"simulation-distance",10);var players=GetInt(props,"max-players",20);var plugins=Directory.Exists(Path.Combine(_profile.Folder,"plugins"))?Directory.EnumerateFiles(Path.Combine(_profile.Folder,"plugins"),"*.jar").Count():0;if(view>12)Add("High","Chunks","Reduce view-distance to 8–12.","High view distance increases chunk generation, network traffic, and memory use.");if(sim>10)Add("High","Entities","Reduce simulation-distance to 6–10.","Simulation distance controls ticking entities and redstone.");if(_profile.MemoryGb<4)Add("High","Memory","Allocate at least 4 GB for a modern small server.","Low heap allocation increases garbage collection pressure and crash risk.");if(_profile.MemoryGb>12&&players<30)Add("Medium","Memory","Consider reducing allocated memory.","Oversized heaps can make garbage-collection pauses longer without improving TPS.");if(plugins>25)Add("Medium","Plugins","Audit plugins and remove overlapping or unused features.","Every plugin adds startup work, listeners, tasks, and compatibility surface.");if(string.Equals(_profile.Type,"Vanilla",StringComparison.OrdinalIgnoreCase)&&players>10)Add("Medium","Platform","Consider Paper or Purpur for larger communities.","Optimized platforms provide tuning options and diagnostics unavailable in Vanilla.");Add("Routine","Backups","Keep automatic backups enabled and test restores.","Performance tuning is safer when world data has a recent recovery point.");Add("Routine","Measurement","Use Spark profiling before aggressive changes.","TPS and MSPT evidence identifies the actual bottleneck more reliably than guesses.");SummaryText.Text=$"Generated {_items.Count} conservative recommendation(s). No settings were changed automatically.";} private Dictionary<string,string> ReadProps(){var d=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);var p=Path.Combine(_profile!.Folder,"server.properties");if(File.Exists(p))foreach(var l in File.ReadLines(p)){var a=l.Split('=',2);if(a.Length==2)d[a[0].Trim()]=a[1].Trim();}return d;} private static int GetInt(Dictionary<string,string>d,string k,int f)=>d.TryGetValue(k,out var v)&&int.TryParse(v,out var n)?n:f; private void Add(string p,string a,string r,string why)=>_items.Add(new OptimizationRecommendation{Priority=p,Area=a,Recommendation=r,Reason=why}); }